Lemma geo_1RB1LC_0LA1RD_1LA0RD_0LC1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_0LA1RD_1LA0RD_0LC1RD) = lift (Cc (Pos.succ p)).
