Lemma fire_1RB1LC_0LC0RB_1LA1RD_0LA0RA : forall t, ~ In t pins_1RB1LC_0LC0RB_1LA1RD_0LA0RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
