  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LC_0LC0RB_1LA1RD_1LD0RA t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1RD_1LD0RA). split;
      [| exact (gbo_1RB1LC_0LC0RB_1LA1RD_1LD0RA j)].
