    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LC_0LC0RB_1LA1RD_1LD0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
