  { unfold Cin_1RB1LC_0LC0RB_1LA1RD_1LD1LA. rewrite epow2_1RB1LC_0LC0RB_1LA1RD_1LD1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LC_0LC0RB_1LA1RD_1LD1LA. rewrite ?lift_app_blank. reflexivity.
