  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1RD_1LD1LA).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LC0RB_1LA1RD_1LD1LA j)].
    rewrite (gso_1RB1LC_0LC0RB_1LA1RD_1LD1LA p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC0RB_1LA1RD_1LD1LA B0_1RB1LC_0LC0RB_1LA1RD_1LD1LA BB1_1RB1LC_0LC0RB_1LA1RD_1LD1LA 4 4
             run_boot_1RB1LC_0LC0RB_1LA1RD_1LD1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 12), (cden [] [] j B1_1RB1LC_0LC0RB_1LA1RD_1LD1LA).
