(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1LC_0LC0RB_1LA1RD_1LD1LA : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1LC_0LC0RB_1LA1RD_1LD1LA = Some q ->
