(** ** The lap *)

Lemma lap_1RB1LC_0LC0RB_1LA1RD_1LD1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
