Lemma fireo_1RB1LC_0LC0RB_1LA1RD_1LD1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LC0RB_1LA1RD_1LD1LA = Some t ->
