(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LC_0LC0RB_1LA1RD_1LD1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LC0RB_1LA1RD_1LD1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LC_0LC0RB_1LA1RD_1LD1LA t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1RD_1LD1LA). split;
      [| exact (gbo_1RB1LC_0LC0RB_1LA1RD_1LD1LA j)].
    rewrite (gso_1RB1LC_0LC0RB_1LA1RD_1LD1LA p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC0RB_1LA1RD_1LD1LA B0_1RB1LC_0LC0RB_1LA1RD_1LD1LA BB1_1RB1LC_0LC0RB_1LA1RD_1LD1LA 4 4
             run_boot_1RB1LC_0LC0RB_1LA1RD_1LD1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LC_0LC0RB_1LA1RD_1LD1LA xH j [] []);
