  - exact bootq_1RB1LC_0LC0RB_1LA1RD_1LD1LA.
  - intros p _. apply lap_1RB1LC_0LC0RB_1LA1RD_1LD1LA.
  - intros t Ht p _. apply fire_1RB1LC_0LC0RB_1LA1RD_1LD1LA. exact Ht.
  - exact wit_1RB1LC_0LC0RB_1LA1RD_1LD1LA.
