    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC0RB_1LA1RD_1RC0RA [SRotL 1; SWin 1; SCycL 2 0; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

