    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LC0RB_1LD1RC_1LA1LA [SCycL 3 0; SWin 3; SWinL 3] (StB, S1) ltac:(vm_compute; reflexivity)
