Lemma gp_1RB1LC_0LC1RA_0LC1RD_1LB0RD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB1LC_0LC1RA_0LC1RD_1LB0RD /\
