    rewrite (srun_sound tm false true chp_1RB1LC_0LC1RA_0LC1RD_1LB0RD P0_1RB1LC_0LC1RA_0LC1RD_1LB0RD P1_1RB1LC_0LC1RA_0LC1RD_1LB0RD 2 10
